/* ====== 颜色变量（方便统一调整配色） ====== */
:root {
  --color-bg: #F5F0EB;
  --color-card: #FFFFFF;
  --color-primary: #8B7355;
  --color-primary-hover: #6B5640;
  --color-text: #3D3226;
  --color-text-light: #7A6E64;
  --color-border: #E0D5C7;
  --color-accent: #D4A574;
  --radius: 12px;
}

/* ====== 筛选按钮区 ====== */
.filter-section {
  display: flex;
  justify-content: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 30px;
}
.filter-btn {
  padding: 8px 20px;
  border: 2px solid var(--color-border);
  border-radius: 24px;
  background: var(--color-card);
  color: var(--color-text);
  font-size: 14px;
  cursor: pointer;
  transition: all 0.2s ease;
}
.filter-btn.active {
  background: var(--color-primary);
  color: #FFFFFF;
  border-color: var(--color-primary);
}

/* ====== 卡片网格 ====== */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
  margin-bottom: 40px;
}

/* ====== 单张音乐卡片 ====== */
.music-card {
  background: var(--color-card);
  border-radius: var(--radius);
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.06);
  overflow: hidden;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.music-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.10);
}
.card-cover {
  width: 100%;
  height: 180px;
  object-fit: cover;
  background: #E8D5C4;
}
.card-info {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.card-info h3 {
  font-size: 18px;
  color: var(--color-text);
  margin: 0;
}
.card-info .composer {
  font-size: 14px;
  color: var(--color-text-light);
  margin: 0;
}
.card-info .tag {
  display: inline-block;
  align-self: flex-start;
  padding: 4px 12px;
  background: #FBF7F0;
  color: var(--color-accent);
  border-radius: 12px;
  font-size: 12px;
}

/* ====== 添加表单区 ====== */
.add-section {
  max-width: 500px;
  margin: 0 auto;
  padding: 24px;
  background: var(--color-card);
  border-radius: var(--radius);
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.06);
}
.add-section h2 {
  font-size: 20px;
  color: var(--color-text);
  margin-bottom: 20px;
  text-align: center;
}
.form-group {
  margin-bottom: 16px;
}
.form-group label {
  display: block;
  font-size: 14px;
  color: var(--color-text-light);
  margin-bottom: 6px;
}
.form-group input,
.form-group select {
  width: 100%;
  padding: 10px 12px;
  border: 2px solid var(--color-border);
  border-radius: 8px;
  font-size: 14px;
  font-family: inherit;
  box-sizing: border-box;
  background: #FAFAFA;
}
.form-group input:focus,
.form-group select:focus {
  outline: none;
  border-color: var(--color-primary);
  background: #FFFFFF;
}
#addBtn {
  width: 100%;
  padding: 12px;
  background: var(--color-primary);
  color: #FFFFFF;
  border: none;
  border-radius: 8px;
  font-size: 16px;
  cursor: pointer;
  margin-top: 8px;
}
#addBtn:hover {
  background: var(--color-primary-hover);
}

